public class Main {
    public static void main(String[] args) {
        //IF
        int score = 85;

        if (score >= 90) {
            System.out.println("Excellent !");
        } else if (score >= 70) {
            System.out.println("Bien joué !");
        } else {
            System.out.println("Encouragements.");
        }

        //FOR
        for (int i = 1; i <= 3; i++) {
            System.out.println("Compteur: " + i);
        }

        //WHILE
        // Boucle équivalente à la boucle for
        int compteur = 0;
        while (compteur < 10) {
            System.out.println("Compteur " + compteur);
            compteur++;
        }

        //DO WHILE
        // Le bloc d'instructions est exécuté au moins une fois
        int compteur = 100;

        do {
            System.out.println("Compteur " + compteur);
            compteur++;
        } while (compteur < 10); //noter le ;
    }
}

